const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function learningInvitations(context){
 const links=bridges[context]||[];
 return `<section class="learning-invitations" aria-label="More places to explore"><h2>Where could this take us?</h2><div class="invitation-links">${links.map(([id,reason])=>{const p=learningPlaces.find(p=>p.id===id);return `<a href="${p.href}"><span aria-hidden="true">${p.mark}</span><strong>${p.title}</strong><small>${esc(reason)}</small></a>`;}).join('')}</div><a class="text-button" href="#explore">See all the connected adventures</a></section>`;
}
export function placeMatches(topicId){return learningPlaces.flatMap(p=>p.topics.filter(t=>t.id===topicId).map(t=>({...p,scope:t.scope})));}
export function learningExplore(graph){
 const nodes=new Map((graph?.topics||[]).map(t=>[t.id,t]));
 return `<div class="page-heading"><a class="back" href="#home">← Back to the garden</a><h1>Follow a curiosity.</h1><p>A parcel, a puddle, a hungry visitor. Start wherever something catches your eye.</p></div><div class="explore-places">${learningPlaces.map(p=>`<article><span class="explore-mark" aria-hidden="true">${p.mark}</span><div><h2>${p.title}</h2><p>${p.body}</p><a class="primary" href="${p.href}">Explore this place</a>${p.topics.length?`<details><summary>Grown-ups: ideas practiced here</summary>${p.topics.map(t=>`<p><a href="#map/${t.id}">${esc(nodes.get(t.id)?.name||'Learning connection')}</a>: ${esc(t.scope)}</p>`).join('')}</details>`:''}</div></article>`).join('')}</div><details class="panel"><summary>Grown-ups: how these places connect</summary><p>The invitations are original story connections, not prerequisite rules. Marble’s learning map separately shows its actual foundation and helpful links. A matching topic can describe only part of an activity; a context-only node has no activity attached. Visiting a place does not demonstrate understanding.</p><p>Help, pauses, and different starting places are welcome. Your unfinished activities stay waiting when you follow a link.</p><a href="#map">Explore the learning map</a></details>`;
}
